import java.util.*;
import java.io.*;

public class Prac {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalNumbers = sc.nextInt();
        int maxBudget = sc.nextInt();
        int[] numbers = new int[totalNumbers];
        for (int index = 0; index < totalNumbers; index++) {
            numbers[index] = sc.nextInt();
        }
        int resultCount = 0;
        int startIndex = 0;
        int evenCount = 0, oddCount = 0;
        List<Integer> differences = new ArrayList<>();
        for (int idx = 0; idx < totalNumbers; idx++) {
            if (numbers[idx] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount && idx != totalNumbers - 1) {
                int diff = Math.abs(numbers[idx + 1] - numbers[startIndex]);
                differences.add(diff);
                startIndex = idx + 1;
                evenCount = 0;
                oddCount = 0;
            }
        }
        if (!differences.isEmpty()) {
            Collections.sort(differences);
            int sumDiffs = 0;
            for (int i = 0; i < differences.size(); i++) {
                sumDiffs += differences.get(i);
                if (sumDiffs > maxBudget) {
                    resultCount = i;
                    break;
                } else {
                    resultCount = i + 1;
                }
            }
