#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int totalNumbers, maxBudget;
    std::cin >> totalNumbers >> maxBudget;
    std::vector<int> numbers(totalNumbers);
    for (int index = 0; index < totalNumbers; ++index) {
        std::cin >> numbers[index];
    }

    int resultCount = 0;
    int startIndex = 0;
    int evenCount = 0, oddCount = 0;
    std::vector<int> differences;

    for (int idx = 0; idx < totalNumbers; ++idx) {
        if (numbers[idx] % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
        if (evenCount == oddCount && idx != totalNumbers - 1) {
            int diff = std::abs(numbers[idx + 1] - numbers[startIndex]);
            differences.push_back(diff);
            startIndex = idx + 1;
            evenCount = 0;
            oddCount = 0;
        }
    }

    if (!differences.empty()) {
        std::sort(differences.begin(), differences.end());
        int sumDiffs = 0;
        for (size_t i = 0; i < differences.size(); ++i) {
            sumDiffs += differences[i];
            if (sumDiffs > maxBudget) {
                resultCount = i;
                break;
            } else {
                resultCount = i + 1;
            }
        }
    } else {
        if (totalNumbers > 0) {
            int singleDiff = std::abs(numbers[0] - numbers[0]);
            if (singleDiff >= maxBudget) {
                resultCount = 1;
            }
        }
    }

    std::cout << resultCount << std::endl;
    return 0;
}
